static var removedSoundFixture(){
    auto sound=synthPresetToJson(factorySynthPresets()[0]);sound.getDynamicObject()->setProperty("schema",5);sound.getDynamicObject()->setProperty("instrument",14);sound.getDynamicObject()->setProperty("name","Former texture");sound["patch"].getDynamicObject()->setProperty("granular",JSON::parse(R"({"source":0,"seed":1234,"sizeMs":120,"density":32,"position":0.2,"spray":0.18,"pitchSpread":0.1,"scan":0.03,"shape":1,"freeze":false})"));return sound;
}
static void testGeneratorRemoval(const File& root){
    expect(instrumentCount==14&&factorySynthPresets().size()==72&&!isSynth((Instrument)14),"removed generator has no selectable identity, synth voice or factory sounds");
    auto p=emptyProject();p.title="Kept song";p.patterns[0].lanes[7]={{0,1,60}};auto old=projectToJson(p);old.getDynamicObject()->setProperty("schema",26);for(auto& track:*old["tracks"].getArray())track["synth"].getDynamicObject()->setProperty("granular",removedSoundFixture()["patch"]["granular"]);
    Project loaded;expect(projectFromJson(old,loaded).wasOk()&&loaded.patterns[0].lanes[7]==p.patterns[0].lanes[7],"schema-26 projects using retained generators migrate without changing notes");expect((int)projectToJson(loaded)["schema"]==projectSchema&&!projectToJson(loaded)["tracks"][7]["synth"].hasProperty("granular"),"new current schema omits removed generator patch fields");
    auto sentinel=JSON::toString(projectToJson(loaded));(*old["tracks"].getArray())[7].getDynamicObject()->setProperty("instrument",14);auto rejected=projectFromJson(old,loaded);expect(rejected.failed()&&rejected.getErrorMessage().contains("removed")&&JSON::toString(projectToJson(loaded))==sentinel,"legacy Granular project rejects with a clear message and preserves the current project");
    auto source=root.getChildFile("removed-generator-original.pulse");source.replaceWithText(JSON::toString(old));auto hash=SHA256(source).toHexString();expect(loadProject(source,loaded).failed()&&SHA256(source).toHexString()==hash,"unsupported legacy song files remain unchanged on disk");
    auto invalid=p;invalid.tracks[7].instrument=(Instrument)14;Assets assets;String warnings;auto playback=std::make_unique<Playback>();expect(compilePlayback(invalid,assets,root,*playback,warnings).failed(),"removed generator cannot silently render as another instrument");
    SynthPreset sound=factorySynthPresets()[0];auto patch=sound.patch;expect(synthPresetFromJson(removedSoundFixture(),sound).failed()&&sound.patch==patch,"removed standalone sound cannot replace the selected sound");
    auto operations=JSON::parse(R"([{"op":"set_song","title":"Must not apply"},{"op":"set_track","track":7,"instrument":"granular"}])");Project destination=p;expect(applyControlEdits(p,operations,destination).failed()&&destination.title==p.title,"MCP rejects removed instrument edits atomically");operations=JSON::parse(R"([{"op":"set_track","track":7,"instrument":"analog","synth":{"granular":{"seed":1}}}])");expect(applyControlEdits(p,operations,destination).failed(),"MCP rejects removed granular parameter overrides");
    SoundLibrary library;library.personal.push_back({"user-retained",factorySynthPresets()[0]});auto json=soundLibraryToJson(library);json.getDynamicObject()->setProperty("schema",5);auto* row=new DynamicObject();row->setProperty("id","user-former");row->setProperty("sound",removedSoundFixture());json["personal"].getArray()->add(var(row));json["favorites"].getArray()->add("user-former");json["favorites"].getArray()->add("factory-14-glass-cloud");SoundLibrary read;
    expect(soundLibraryFromJson(json,read).wasOk()&&read.personal.size()==1&&read.removedSounds.size()==1&&read.removedFavorites.size()==2,"legacy removed sounds are hidden while other personal sounds remain usable");SynthPreset result;expect(!resolveLibrarySound(read,"user-former",result)&&!resolveLibrarySound(read,"factory-14-glass-cloud",result)&&resolveLibrarySound(read,"user-retained",result),"retained legacy data cannot be recalled as an active generator");
    auto catalog=root.getChildFile("removal-sound-library.json");catalog.replaceWithText(JSON::toString(json,false,22));auto saved=putPersonalSound(catalog,{"user-new",factorySynthPresets()[24]});SoundLibrary reopened;expect(saved.wasOk()&&loadSoundLibrary(catalog,reopened).wasOk()&&reopened.personal.size()==2&&reopened.removedSounds.size()==1&&JSON::toString(reopened.removedSounds[0])==JSON::toString(read.removedSounds[0])&&reopened.removedFavorites==read.removedFavorites,"normal library edits preserve opaque removed sound data and its favorites");
    hash=SHA256(catalog).toHexString();expect(putPersonalSound(catalog,{"user-former",factorySynthPresets()[25]}).failed()&&SHA256(catalog).toHexString()==hash,"hidden legacy identities cannot be overwritten by a new sound");
}
